// Generates src/ui/kit-css.generated.ts from the hub-owned Harness UI CSS.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const read = (name) => {
  try {
    return readFileSync(fileURLToPath(new URL(`.harness/design-system/${name}`, root)), "utf8");
  } catch {
    process.stderr.write(`Run harness sync first: .harness/design-system/${name} is missing\n`);
    process.exit(1);
  }
};

const tokens = read("tokens.css");
const bundle = read("bundle.css");

const out =
  "// GENERATED by scripts/build-kit-css.mjs. Do not edit.\n" +
  "// Sources: .harness/design-system/tokens.css and .harness/design-system/bundle.css (hub-owned).\n" +
  `export const TOKENS_CSS = ${JSON.stringify(tokens)};\n` +
  `export const BUNDLE_CSS = ${JSON.stringify(bundle)};\n`;

writeFileSync(fileURLToPath(new URL("src/ui/kit-css.generated.ts", root)), out);
